sys_variable_value.value:
(function execute(inputs, outputs) {
    var ports = new GlideRecord('x_snc_duty_travel_ports');
    ports.addEncodedQuery('port='+inputs.port);
    ports.query();
    if(ports.next()) {
        outputs.country = ports.country.getDisplayValue();
    }
})(inputs, outputs);

